WITH kept AS (SELECT s.* FROM products s WHERE NOT EXISTS (SELECT 1 FROM order_items c WHERE c.product_id = s.id AND c.unit_price >= 330)) SELECT CASE WHEN price >= 1190 THEN 'HIGH' ELSE 'LOW' END AS price_tier, brand, ROUND(AVG(cost), 2) AS avg_cost, COUNT(*) FILTER (WHERE brand = 'Initech') AS initech_rows, APPROX_PERCENTILE(stock_qty, ARRAY(0.25, 0.5, 0.75)) AS stock_qty_quartiles, GROUPING_ID() AS gid FROM kept GROUP BY ROLLUP (CASE WHEN price >= 1190 THEN 'HIGH' ELSE 'LOW' END, brand) ORDER BY price_tier DESC
